def task_conflicts(intervals):
    intervals = sorted(intervals)
    total = 0
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if intervals[j][0] >= intervals[i][1]:
                break
            total += 1
    return total

def battery_schedule(jobs, battery):
    used = 0
    completed = 0
    for duration, cost in sorted(jobs, key=lambda job: (job[1], job[0])):
        if used + cost <= battery:
            used += cost
            completed += 1
        else:
            break
    return completed

def group_anagram_sizes(words):
    groups = {}
    for word in words:
        key = ''.join(sorted(word))
        groups[key] = groups.get(key, 0) + 1
    return sorted(groups.values(), reverse=True)

def window_max_sum(nums, k):
    if k <= 0 or k > len(nums):
        return None
    current = sum(nums[:k])
    best = current
    for i in range(k, len(nums)):
        current += nums[i] - nums[i-k]
        best = max(best, current)
    return best
